# Curadoria de músicas famosas "de onde é?": desenhos, Disney/animações, animes, filmes/séries e jogos.
# Ordem = fama estimada para o público brasileiro (prio menor gera antes).
# Campos: c categoria (disney|desenhos|filmes|jogos), tp tipo, o obra, oa outros nomes da obra,
# t título principal (versão em português quando existir), al títulos alternativos que também valem,
# a intérprete esperado (filtra covers na Deezer), q buscas na Deezer, y busca no YouTube, yt=True força YouTube
# (dublagens brasileiras e trilhas da Nintendo não estão na Deezer).

def E(c, o, t, al=(), a=None, q=None, y=None, p=200, oa=(), tp=None, yt=False, ini=None):
    return dict(c=c, o=o, t=t, al=list(al), a=a, q=list(q or []), y=y, p=p, oa=list(oa), tp=tp or {'disney': 'disney', 'desenhos': 'desenho', 'filmes': 'filme', 'jogos': 'jogo'}[c], yt=yt, ini=ini)

